        /* 1. Global Fade Loop (Jeda 1 Detik di akhir) */
        .squad-fade { animation: fade-loop 5s infinite; }

        /* 2. Animasi Dev Squad (Scalable / On-Demand) */
        .dev-1 { transform-origin: 75px 25px; animation: pop-dev 5s infinite; animation-delay: 0s; }
