        /* Siklus Utama (Muncul, Tahan, Hilang, Jeda) */
        @keyframes fade-loop {
            0%, 5% { opacity: 0; }
            10%, 75% { opacity: 1; }
            80%, 100% { opacity: 0; }
        }

        /* Dev Pop-up */
        @keyframes pop-dev {
            0%, 10% { transform: scale(0); opacity: 0; }
            15%, 80% { transform: scale(1); opacity: 1; }
            85%, 100% { transform: scale(0); opacity: 0; }
        }

        /* Garis Koneksi Digambar */
        @keyframes draw-conn {
            0%, 10% { stroke-dashoffset: 40; }
            20%, 80% { stroke-dashoffset: 0; }
            85%, 100% { stroke-dashoffset: 40; }
        }

        /* Rotasi Siklus (Makin lama makin cepat) */
        @keyframes spin-cycle {
            0% { transform: rotate(0deg); }
            20% { transform: rotate(90deg); }   /* Lambat (1 dev) */
            40% { transform: rotate(360deg); }  /* Sedang (2 dev) */
            60%, 80% { transform: rotate(1440deg); } /* SANGAT CEPAT (3 dev) */
            100% { transform: rotate(1440deg); }
        }

        /* Boost Petir Muncul saat siklus sangat cepat */
        @keyframes pop-boost {
            0%, 50% { transform: scale(0); opacity: 0; }
            55%, 75% { transform: scale(1); opacity: 1; }
            80%, 100% { transform: scale(0); opacity: 0; }
        }

        /* Garis Kecepatan (Speed Lines) */
        @keyframes pop-lines {
            0%, 50% { transform: scale(0.5) rotate(-20deg); opacity: 0; }
            55% { transform: scale(1.1) rotate(0deg); opacity: 1; }
            60%, 75% { transform: scale(1) rotate(0deg); opacity: 1; }
            80%, 100% { transform: scale(0.5) rotate(20deg); opacity: 0; }
        }

        /* --- STYLING --- */
        .color-primary { fill: #3B82F6; } /* Biru */
        .color-secondary { fill: #8B5CF6; } /* Ungu */
        .color-accent { fill: #10B981; } /* Hijau */
        .stroke-thick { stroke-width: 2.5px; stroke-linecap: round; stroke-linejoin: round; fill: none; }
      </style><g class="squad-fade" style="opacity:0"><path class="stroke-thick conn-line conn-1" d="M68 30 Q55 35 45 42" stroke="#CBD5E1"></path><path class="stroke-thick conn-line conn-2" d="M75 50 L52 50" stroke="#CBD5E1"></path><path class="stroke-thick conn-line conn-3" d="M68 70 Q55 65 45 58" stroke="#CBD5E1"></path><g class="dev-1" style="opacity:0"><circle class="color-primary" cx="75" cy="20" r="5"></circle><path d="M67 32 C67 26 83 26 83 32" fill="none" stroke="#3B82F6" stroke-linecap="round" stroke-width="3"></path><path d="M82 16 L86 16 M84 14 L84 18" stroke="#10B981" stroke-linecap="round" stroke-width="1.5"></path></g><g class="dev-2" style="opacity:0"><circle class="color-secondary" cx="85" cy="45" r="5"></circle><path d="M77 57 C77 51 93 51 93 57" fill="none" stroke="#8B5CF6" stroke-linecap="round" stroke-width="3"></path><path d="M92 41 L96 41 M94 39 L94 43" stroke="#10B981" stroke-linecap="round" stroke-width="1.5"></path></g><g class="dev-3" style="opacity:0"><circle cx="75" cy="70" fill="#1E40AF" r="5"></circle><path d="M67 82 C67 76 83 76 83 82" fill="none" stroke="#1E40AF" stroke-linecap="round" stroke-width="3"></path><path d="M82 66 L86 66 M84 64 L84 68" stroke="#10B981" stroke-linecap="round" stroke-width="1.5"></path></g><g class="speed-lines"><circle cx="35" cy="50" fill="#D1FAE5" r="22"></circle> <path d="M8 50 L14 50 M12 35 L18 38 M12 65 L18 62" stroke="#34D399" stroke-linecap="round" stroke-width="2"></path></g><g class="dev-cycle"><path class="stroke-thick" d="M22 40 A15 15 0 0 1 48 45" stroke="#475569"></path><polygon fill="#475569" points="48,41 52,48 44,48" transform="rotate(-20 48 45)"></polygon><path class="stroke-thick" d="M48 60 A15 15 0 0 1 22 55" stroke="#475569"></path><polygon fill="#475569" points="22,59 18,52 26,52" transform="rotate(-20 22 55)"></polygon></g><g><path d="M31 46 L27 50 L31 54 M39 46 L43 50 L39 54" fill="none" stroke="#0F172A" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"></path><line strok